public String isValid(String s) {
    if (uniform(freqOf(s))) return "YES";
    for (int i = 0; i < s.length(); i++) {
        StringBuilder sb = new StringBuilder(s);
        sb.deleteCharAt(i);
        if (uniform(freqOf(sb.toString()))) {
            return "YES";
        }
    }
    return "NO";
}

private int[] freqOf(String s) {
    int[] f = new int[26];
    for (int i = 0; i < s.length(); i++) f[s.charAt(i) - 'a']++;
    return f;
}

private boolean uniform(int[] f) {
    int target = 0;
    for (int c : f) {
        if (c == 0) continue;
        if (target == 0) target = c;
        else if (c != target) return false;
    }
    return true;
}

