def isValid(self, s: str) -> str:
    from collections import Counter

    def uniform(counts: list[int]) -> bool:
        nonzero = [c for c in counts if c > 0]
        return len(set(nonzero)) <= 1

    base = [0] * 26
    for ch in s:
        base[ord(ch) - 97] += 1
    if uniform(base):
        return "YES"
    for i in range(len(s)):
        trial = list(base)
        trial[ord(s[i]) - 97] -= 1
        if uniform(trial):
            return "YES"
    return "NO"

