public String isValid(String s) {
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) freq[s.charAt(i) - 'a']++;
    Map<Integer, Integer> counts = new HashMap<>();
    for (int f : freq) {
        if (f > 0) counts.merge(f, 1, Integer::sum);
    }
    if (counts.size() == 1) return "YES";
    if (counts.size() == 2) {
        List<Integer> keys = new ArrayList<>(counts.keySet());
        Collections.sort(keys);
        int f1 = keys.get(0), f2 = keys.get(1);
        int c1 = counts.get(f1), c2 = counts.get(f2);
        if (f1 == 1 && c1 == 1) return "YES";
        if (f2 - f1 == 1 && c2 == 1) return "YES";
    }
    return "NO";
}

