    from collections import Counter
    freq = Counter(s)
    counts = Counter(freq.values())
    if len(counts) == 1:
        return "YES"
    if len(counts) == 2:
        (f1, c1), (f2, c2) = sorted(counts.items())
        if f1 == 1 and c1 == 1:
            return "YES"
        if f2 - f1 == 1 and c2 == 1:
            return "YES"
    return "NO"

